def load_series(data_dir):
    with open(os.path.join(data_dir, "all_metrics.json")) as f:
        data = json.load(f)
    data.sort(key=lambda x: x["generation"])
    return {k: np.array([d[k] for d in data]) for k in CANARIES + DOWNSTREAMS}, len(data)


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def naive_xcorr(c, d, cn, dn):
    x, y = orient(c, cn), orient(d, dn)
    n = len(x)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-XCORR_LAG, XCORR_LAG + 1):
        if lag >= 0:
            a, b = x[lag:], y[:n - lag]
        else:
            a, b = x[:n + lag], y[-lag:]
        if len(a) < 4:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {"significant": bool(best_p < ALPHA), "peak_lag": int(best_lag),
            "r": round(float(best_r), 4), "p_value": round(float(best_p), 6)}


def diff_xcorr(c, d, cn, dn):
    dx, dy = np.diff(orient(c, cn)), np.diff(orient(d, dn))
    n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-XCORR_LAG, XCORR_LAG + 1):
        if lag >= 0:
            a, b = dx[lag:], dy[:n - lag]
        else:
            a, b = dx[:n + lag], dy[-lag:]
        if len(a) < 4:
            continue
        if np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {"significant": bool(best_p < ALPHA), "peak_lag": int(best_lag),
            "r": round(float(best_r), 4), "p_value": round(float(best_p), 6)}


def _onset_gen(series, name):
    s = orient(series, name)
    base, sigma = s[0], np.std(s)
    if sigma < 1e-12:
        return None
    thresh = base + THRESHOLD_SIGMA * sigma
    for i in range(1, len(s)):
        if s[i] > thresh:
            return i
    return None


def threshold_onset(c, d, cn, dn):
    c_onset, d_onset = _onset_gen(c, cn), _onset_gen(d, dn)
    if c_onset is not None and d_onset is not None:
        lead = d_onset - c_onset
        sig = lead > 0
    else:
        lead, sig = None, False
    return {"significant": sig, "canary_onset": c_onset,
            "downstream_onset": d_onset, "lead_time": lead,
            "threshold": f"{THRESHOLD_SIGMA}x_sigma_drift"}


def perm_granger(c, d, cn, dn, seed=42):
    x, y = orient(c, cn), orient(d, dn)
    r = permutation_granger_test(x, y, max_lag=GRANGER_LAG, n_perm=N_PERM,
                                  seed=seed, difference=True)
    p = r.get("p_value")
    return {"significant": bool(p is not None and p < ALPHA),
            "f_stat": round(float(r["f_stat"]), 4) if r["f_stat"] is not None else None,
            "p_value": round(float(p), 6) if p is not None else None,
            "n_perm": N_PERM}


